// Customer-facing view of the dunning ladder.
//
// WHY THIS FILE EXISTS
// `worker/billing.ts` owns the dunning POLICY, and every constant that shapes it
// (`retryDayFor`, `CARD_SUSPEND_DAY`, `DUNNING_EXHAUSTED`, `SUSPEND_SLIP_CAP_DAYS`,
// `suspendDueAt`) is module-private there. The portal cannot import them: that file
// pulls in the provisioning worker's whole world — Proxmox, nodemailer, the job
// queue — and none of it belongs in a page bundle.
//
// So the DAY ARITHMETIC is duplicated here, deliberately, and each constant is
// named exactly as the worker names it so a change to the schedule is greppable.
// This is the same trade `lib/actions-settings.ts` already makes for
// MIN_TERMINATE_DAYS, and it is guarded the same way: `test/payment-method-ui.test.ts`
// reads worker/billing.ts and fails the moment the two disagree.
//
// DUNNING_RETRY_ATTEMPTS itself is IMPORTED rather than copied. It is the one number
// the dunning emails subtract from ("we'll try 2 more times"), and a second copy of
// it is precisely how that promise starts outliving the retries that back it.
//
// Plain server module. Everything below is pure arithmetic on the columns the worker
// writes, so a server component can compute the view once and hand plain data to a
// client component — no clock or database access hides in here.

import { DUNNING_RETRY_ATTEMPTS } from "./mailer";

export { DUNNING_RETRY_ATTEMPTS };

const DAY = 86_400_000;

/** Mirrors `const retryDayFor = (retry: number) => 2 * retry - 1;` in worker/billing.ts. */
export const retryDayFor = (retry: number) => 2 * retry - 1;
/** Mirrors `const CARD_SUSPEND_DAY = LAST_RETRY_DAY + 1;` — one clear day after the final notice. */
const SUSPEND_DAYS_AFTER_LAST_RETRY = 1;
/** Mirrors `const SUSPEND_SLIP_CAP_DAYS = 4;` in worker/billing.ts. */
export const SUSPEND_SLIP_CAP_DAYS = 4;
/**
 * Mirrors `const CARD_EXPIRY_WARN_DAYS = 30;` in worker/billing.ts — how far ahead
 * the worker emails about a card that is about to expire. The portal flags the card
 * on exactly the same day the email goes out, so the two never disagree about
 * whether a card counts as "expiring soon".
 */
export const CARD_EXPIRY_WARN_DAYS = 30;

/** Days past expiry on which the worker retries the saved card. */
export const RETRY_DAYS: number[] = Array.from({ length: DUNNING_RETRY_ATTEMPTS }, (_, i) =>
  retryDayFor(i + 1),
);
/** Days past expiry of the LAST automatic retry. */
export const LAST_RETRY_DAY = retryDayFor(DUNNING_RETRY_ATTEMPTS);
/** Days past expiry when a card customer's server pauses, if nothing has been paid. */
export const CARD_SUSPEND_DAY = LAST_RETRY_DAY + SUSPEND_DAYS_AFTER_LAST_RETRY;
/**
 * `Server.dunningStage` once every automatic attempt is spent: the attempt made on
 * expiry day itself, plus one per retry. Mirrors
 * `const DUNNING_EXHAUSTED = DUNNING_RETRY_ATTEMPTS + 1;`.
 */
export const DUNNING_EXHAUSTED = DUNNING_RETRY_ATTEMPTS + 1;

/** The columns `worker/billing.ts` reads to decide what happens to an overdue server. */
export type DunningInput = {

  return process.env.APP_URL ?? "http://localhost:3000";
}

/** Audit actions used to decide whether an unclaimed Stripe card may be adopted. */
export const CARD_SETUP_STARTED = "card.setup_started";
export const CARD_REMOVED = "card.removed";

/** How long a "I clicked Add card" intent stays good for the adoption backstop. */
const SETUP_INTENT_TTL_DAYS = 7;

export type CardDisplay = {
  brand: string | null;
  last4: string | null;
  expMonth: number | null;
  expYear: number | null;
};

/** "Visa ···· 4242, expires 04/28" — one formatter for UI, email and audit text. */
export function cardDisplayLabel(card: CardDisplay): string | null {
  if (!card.last4) return null;
  const brand = brandLabel(card.brand);
  const expiry =
    card.expMonth && card.expYear
      ? `, expires ${String(card.expMonth).padStart(2, "0")}/${String(card.expYear).slice(-2)}`
      : "";
  return `${brand} ···· ${card.last4}${expiry}`;
}

/** Stripe brand ids are lowercase slugs ("visa", "amex", "unionpay"). */
export function brandLabel(brand: string | null | undefined): string {
  const map: Record<string, string> = {
    visa: "Visa",
    mastercard: "Mastercard",
    amex: "American Express",
    discover: "Discover",
    diners: "Diners Club",
    jcb: "JCB",
    unionpay: "UnionPay",
    cartes_bancaires: "Cartes Bancaires",
    eftpos_au: "Eftpos",
    link: "Link",
  };
  if (!brand) return "Card";
  return map[brand] ?? brand.replace(/_/g, " ").replace(/\b\w/g, (c) => c.toUpperCase());
}

/**
 * A card is valid THROUGH the last day of its expiry month, so it stops working
 * at the first instant of the following month. Getting this off by a month would
 * either nag customers a month early or warn them after the renewal already failed.
 */
export function cardExpiresAt(expMonth: number, expYear: number): Date {
  return new Date(Date.UTC(expYear, expMonth, 1));
}

/* ------------------------------------------------------------------ *
 * Renewal pricing — ONE formula, two callers
 * ------------------------------------------------------------------ */

/**
 * What a renewal costs. Lives here (rather than being copied a third time)
 * because BOTH the worker sweep and the customer-facing "settle the balance"
 * link have to quote the same number — `renewNow` and the sweep already carry
 * the comment "the two renewal paths must never disagree", and a self-service
 * pay link that quotes a different total than the sweep charges is exactly how
 * that goes wrong.
 *
 * Pure: prices are passed in so the worker can read the admin settings once per
 * sweep instead of once per server.
 */
// `renewalCharge` and its types now live in ./renewal-charge — a pure module with
// no SDK imports, so client components can price a renewal without pulling the
// Stripe SDK and nodemailer into the browser bundle. Re-exported here so every
// existing server-side importer keeps working unchanged.
export { renewalCharge, type RenewalCharge, type PricedServer } from "./renewal-charge";

/* ------------------------------------------------------------------ *
 * Stripe customer + saving a card
 * ------------------------------------------------------------------ */

export type CardUser = {
  id: string;
  email: string;
  name?: string | null;
  stripeCustomerId: string | null;
  stripePaymentMethodId: string | null;
};

/** True when this account can actually be charged off-session right now. */
export function hasChargeableCard(user: {
  stripeCustomerId: string | null;
  stripePaymentMethodId: string | null;
}): boolean {
  return stripeConfigured() && !!user.stripeCustomerId && !!user.stripePaymentMethodId;
}

/**
 * Get-or-create the Stripe customer for an account and remember its id.
 *
 * `User.stripeCustomerId` has no UNIQUE constraint (the schema is frozen), so two
 * concurrent "Add card" clicks could otherwise mint two Stripe customers for one
 * person and strand the card on whichever one lost. The idempotency key — derived
 * only from our own user id — is what stops that: Stripe replays the first
 * customer instead of creating a second.
 */
export async function ensureStripeCustomer(user: CardUser): Promise<string> {
  if (user.stripeCustomerId) return user.stripeCustomerId;
  const fresh = await db.user.findUnique({
    where: { id: user.id },
    select: { stripeCustomerId: true },
  });
  if (fresh?.stripeCustomerId) return fresh.stripeCustomerId;

  const customer = await stripe().customers.create(
    {
      email: user.email,
      name: user.name || undefined,
      metadata: { nxeonUserId: user.id },
    },
    { idempotencyKey: `nxeon_customer_${user.id}` },
  );

