import { cardDisplayLabel, hasChargeableCard } from "@/lib/stripe-cards";

// ---------------------------------------------------------------------------
// Per-customer, READ-ONLY diagnostic tools for the AI chat assistant.
//
// Every query in this file is scoped to the trusted `userId` FUNCTION ARGUMENT
// (the signed-in customer). The tool `input` is NEVER trusted to carry a userId
// or any ownership claim — it may only carry a service `id`, which is then
// re-checked to belong to `userId` before anything is returned. Nothing here
// writes, updates, or deletes; nothing here returns another user's row.
//
// Grounding (all confirmed against prisma/schema.prisma):
//   - Server            userId  — VPS, game servers (gamePlanId), NxCloud VMs
//   - HostingAccount    userId  — shared hosting
//   - Domain            userId
//   - EmailSubscription userId  — business email (Mailbox via subscription)
//   - Volume            userId  — block-storage add-on disks
//   - NxCloudInstance   userId  — managed Nextcloud
//   - Invoice           userId  — money in integer CENTS
//   - WalletTransaction userId  — wallet credits/debits in CENTS
//   - Ticket            userId  — support tickets
//   - User              balanceCents, signupCreditCents, card* mirror fields
//
// Money is stored as integer CENTS everywhere and displayed with formatMoney()
// in the account's configured display currency (default USD). Secrets
// (rootPassword*, *PasswordEnc, *PassEnc, tokens) are never read or returned;
// only the stored card brand/last4 are surfaced.
// ---------------------------------------------------------------------------

/** Statuses treated as "still open" for a support ticket (i.e. not CLOSED). */
const OPEN_TICKET_STATUSES = ["OPEN", "ANSWERED", "CUSTOMER_REPLY"] as const;

/** "2026-08-15" or "—" for a nullable date. */
function ymd(d: Date | null | undefined): string {
  return d ? d.toISOString().slice(0, 10) : "—";
}

/** Short, model-friendly one-liner joiner. */
function lines(...parts: (string | false | null | undefined)[]): string {
  return parts.filter(Boolean).join("\n");
}

/** Classify a Server row into a customer-facing service type. */
function serverType(s: { gamePlanId: string | null; nxcloudInstance: unknown | null }): string {
  if (s.nxcloudInstance) return "nxcloud";
  if (s.gamePlanId) return "game";
  return "vps";
}

export const ACCOUNT_TOOLS: ClaudeToolDef[] = [
  {
    name: "get_account_overview",
    description:
      "One-shot summary of the signed-in customer's account — call this FIRST to " +
      "orient. Reports how many of each service they have and the status mix, any " +
      "unpaid invoices, whether a payment card is on file, the count of open " +
      "support tickets, and the wallet balance / account credit. No input.",
    input_schema: { type: "object", properties: {}, required: [] },
  },
  {
    name: "list_services",
    description:
      "List the customer's services (VPS, game servers, managed Nextcloud, shared " +
      "hosting accounts, business-email subscriptions, block-storage volumes, and " +
      "domains). Each entry gives an id (use it with get_service), a human label, " +
      "the type, current status, plan name, and next renewal/expiry date. No input.",
    input_schema: { type: "object", properties: {}, required: [] },
  },
  {
    name: "get_service",
    description:
      "Detail for ONE service the customer owns, by its id (from list_services). " +
      "Returns status, hostname/IP or domain where applicable, key specs, plan, " +
      "renewal date, and the most recent error/state note if any. Returns a short " +
      "'not found or not yours' message if the id is not owned by this customer.",
    input_schema: {
      type: "object",
      properties: {
        id: { type: "string", description: "The service id shown by list_services." },
      },
      required: ["id"],
    },
  },
  {
    name: "list_invoices",
    description:
      "The customer's most recent invoices: number, date, amount + currency, " +
      "status (OPEN=unpaid, PAID, VOID, REFUNDED), and what each was for. " +
      "Optional { limit } (default 10, max 10).",
    input_schema: {
      type: "object",
      properties: {
        limit: {
          type: "integer",
          description: "How many recent invoices to return (1-10, default 10).",
          minimum: 1,
          maximum: 10,
        },
      },
      required: [],
    },
  },
  {
    name: "get_billing_status",
    description:
      "The customer's billing health: whether a payment card is on file " +
      "(brand + last4 only), any unpaid invoices, any past-due services and their " +
      "dunning (failed-charge retry) state, the next scheduled renewal date, and " +
      "the wallet balance / account credit. No input.",
    input_schema: { type: "object", properties: {}, required: [] },
  },
  {
    name: "list_tickets",
    description:
      "The customer's OPEN support tickets (not closed): id, subject, status, " +
      "priority, message count, and last-updated date. No input.",
    input_schema: { type: "object", properties: {}, required: [] },
  },
];

// ---------------------------------------------------------------------------
// Executor
// ---------------------------------------------------------------------------

/**
 * Execute a tool STRICTLY scoped to `userId`. Read-only. Returns a concise,
 * model-friendly string. Never returns another user's data. On an unknown tool
 * or any error, returns a short error string (never throws).
 */
export async function runAccountTool(
  userId: string,
  name: string,
  input: unknown,
): Promise<string> {
  try {
    if (!userId) return "Error: no signed-in customer.";
    const currency = await currentCurrency();
    const money = (cents: number) => formatMoney(cents, currency);

    switch (name) {
      case "get_account_overview":
        return await accountOverview(userId, money);
      case "list_services":
        return await listServices(userId);
      case "get_service":
        return await getService(userId, input);
      case "list_invoices":
        return await listInvoices(userId, input, money);
      case "get_billing_status":
        return await billingStatus(userId, money);
      case "list_tickets":
        return await listTickets(userId);
      default:
        return `Error: unknown tool "${name}".`;
    }
  } catch (err) {
    const msg = err instanceof Error ? err.message : String(err);
    return `Error running ${name}: ${msg}`;
  }
}

// ---------------------------------------------------------------------------
// Tool implementations (each scoped to userId)
// ---------------------------------------------------------------------------

async function accountOverview(userId: string, money: (c: number) => string): Promise<string> {
  const now = new Date();
  const [user, servers, hosting, emailSubs, domains, volumes, openInvoices, openTickets] =
    await Promise.all([
      db.user.findUnique({
        where: { id: userId },
        select: {
          balanceCents: true,
          signupCreditCents: true,
          cardBrand: true,
          cardLast4: true,
          cardExpMonth: true,
          cardExpYear: true,
          stripeCustomerId: true,
          stripePaymentMethodId: true,
        },
      }),
      db.server.findMany({
        where: { userId, status: { not: "DELETING" } },
        select: { status: true, gamePlanId: true, nxcloudInstance: { select: { id: true } } },
      }),
      db.hostingAccount.groupBy({
        by: ["status"],
        where: { userId, status: { not: "DELETING" } },
        _count: true,
      }),
      db.emailSubscription.count({ where: { userId } }),
      db.domain.count({ where: { userId } }),
      db.volume.count({ where: { userId, status: { not: "DELETING" } } }),
      db.invoice.findMany({
        where: { userId, status: "OPEN" },
        select: { amountCents: true },
      }),
      db.ticket.count({ where: { userId, status: { in: OPEN_TICKET_STATUSES as unknown as string[] } } }),
    ]);

  if (!user) return "Error: customer not found.";

  // Server breakdown by type + status.
  const vps = servers.filter((s) => !s.gamePlanId && !s.nxcloudInstance);
  const game = servers.filter((s) => s.gamePlanId && !s.nxcloudInstance);
  const nxcloud = servers.filter((s) => s.nxcloudInstance);
  const statusMix = (rows: { status: string }[]) => {
    const m: Record<string, number> = {};
    for (const r of rows) m[r.status] = (m[r.status] ?? 0) + 1;
    return Object.entries(m)
      .map(([k, v]) => `${v} ${k}`)
      .join(", ");
  };

  const svcLine = (label: string, rows: { status: string }[]) =>
    rows.length ? `${label}: ${rows.length} (${statusMix(rows)})` : null;

  const hostingTotal = hosting.reduce((n, h) => n + h._count, 0);
  const hostingMix = hosting.map((h) => `${h._count} ${h.status}`).join(", ");

  const cardLabel = cardDisplayLabel(user);
  const overdueServers = await db.server.count({
    where: { userId, isFree: false, expiresAt: { lt: now }, status: { in: ["RUNNING", "STOPPED", "SUSPENDED"] } },
  });

  const unpaidTotal = openInvoices.reduce((n, i) => n + i.amountCents, 0);
  const creditCents = user.balanceCents + user.signupCreditCents;

  return lines(
    "ACCOUNT OVERVIEW",
    "Services:",
    svcLine("  VPS", vps),
    svcLine("  Game servers", game),
    svcLine("  Managed Nextcloud", nxcloud),
    hostingTotal ? `  Shared hosting: ${hostingTotal} (${hostingMix})` : null,
    emailSubs ? `  Business email: ${emailSubs} subscription(s)` : null,
    domains ? `  Domains: ${domains}` : null,
    volumes ? `  Storage volumes: ${volumes}` : null,
    !vps.length && !game.length && !nxcloud.length && !hostingTotal && !emailSubs && !domains && !volumes
      ? "  (no active services)"
      : null,
    "Billing:",
    `  Payment card on file: ${cardLabel ? cardLabel : "none"}${cardLabel && !hasChargeableCard(user) ? " (not currently chargeable)" : ""}`,
    `  Unpaid invoices: ${openInvoices.length}${openInvoices.length ? ` totaling ${money(unpaidTotal)}` : ""}`,
    overdueServers ? `  Past-due services in dunning: ${overdueServers}` : "  Past-due services: 0",
    `  Wallet balance / credit: ${money(creditCents)}`,
    `Open support tickets: ${openTickets}`,
  );
}

async function listServices(userId: string): Promise<string> {
  const [servers, hosting, emailSubs, domains, volumes] = await Promise.all([
    db.server.findMany({
      where: { userId, status: { not: "DELETING" } },
      select: {
        id: true,
        name: true,
        label: true,
        status: true,
        expiresAt: true,
        gamePlanId: true,
        plan: { select: { name: true } },
        gamePlan: { select: { name: true, gameFamily: true } },
        nxcloudInstance: { select: { id: true, subdomain: true } },
      },
      orderBy: { createdAt: "asc" },
      take: 20,
    }),
    db.hostingAccount.findMany({
      where: { userId, status: { not: "DELETING" } },
      select: {
        id: true,
        primaryDomain: true,
        status: true,
        expiresAt: true,
        plan: { select: { name: true } },
      },
      orderBy: { createdAt: "asc" },
      take: 20,
    }),
    db.emailSubscription.findMany({
      where: { userId },
      select: {
        id: true,
        domainName: true,
        status: true,
        expiresAt: true,
        emailPlan: { select: { name: true } },
      },
      orderBy: { createdAt: "asc" },
      take: 20,
    }),
    db.domain.findMany({
      where: { userId },
      select: { id: true, name: true, status: true, expiresAt: true },
      orderBy: { createdAt: "asc" },
      take: 20,
    }),
    db.volume.findMany({
      where: { userId, status: { not: "DELETING" } },
      select: { id: true, name: true, status: true, sizeGB: true, expiresAt: true },
      orderBy: { createdAt: "asc" },
      take: 20,
    }),
  ]);

  const out: string[] = [];

  for (const s of servers) {
    const type = serverType(s);
    const label = s.label || s.name;
    const plan =
      type === "game"
        ? s.gamePlan?.name || `game (${s.gamePlan?.gameFamily ?? "?"})`
        : type === "nxcloud"
          ? `Nextcloud @ ${s.nxcloudInstance?.subdomain ?? "?"}`
          : s.plan?.name || "?";
    out.push(
      `[${s.id}] ${label} — type=${type} status=${s.status} plan="${plan}" renews=${ymd(s.expiresAt)}`,
    );
  }
  for (const h of hosting) {
    out.push(
      `[${h.id}] ${h.primaryDomain} — type=hosting status=${h.status} plan="${h.plan?.name ?? "?"}" renews=${ymd(h.expiresAt)}`,
    );
  }
  for (const e of emailSubs) {
    out.push(
      `[${e.id}] ${e.domainName} — type=email status=${e.status} plan="${e.emailPlan?.name ?? "?"}" renews=${ymd(e.expiresAt)}`,
    );
  }
  for (const d of domains) {
    out.push(`[${d.id}] ${d.name} — type=domain status=${d.status} expires=${ymd(d.expiresAt)}`);
  }
  for (const v of volumes) {
    out.push(
      `[${v.id}] ${v.name} — type=volume status=${v.status} size=${v.sizeGB}GB renews=${ymd(v.expiresAt)}`,
    );
  }

  if (!out.length) return "This customer has no active services.";
  return lines("SERVICES (id — label — details):", ...out);
}

async function getService(userId: string, input: unknown): Promise<string> {
  const id = typeof input === "object" && input && "id" in input ? String((input as { id: unknown }).id) : "";
  if (!id) return "Error: get_service requires an 'id'.";

  // Every lookup is filtered by BOTH id AND userId, so a foreign id returns null.
  // --- Server (VPS / game / NxCloud VM) ---
  const server = await db.server.findFirst({
    where: { id, userId },
    select: {
      id: true,
      name: true,
      label: true,
      hostname: true,
      status: true,
      ipAddress: true,
      ipv6: true,
      gamePlanId: true,
      gameVariant: true,
      expiresAt: true,
      autoRenew: true,
      isFree: true,
      termMonths: true,
      extraDiskGB: true,
      suspendReason: true,
      provisionError: true,
      dunningStage: true,
      plan: { select: { name: true, cpuCores: true, ramMB: true, diskGB: true } },
      gamePlan: { select: { name: true, gameFamily: true, ramMB: true, slots: true } },
      nxcloudInstance: {
        select: { subdomain: true, status: true, version: true, storageQuotaMB: true, storageUsedMB: true },
      },
    },
  });
  if (server) {
    const type = serverType(server);
    const specs = server.plan
      ? `${server.plan.cpuCores} vCPU / ${server.plan.ramMB} MB RAM / ${server.plan.diskGB + (server.extraDiskGB ?? 0)} GB disk`
      : "?";
    return lines(
      `SERVICE ${server.id} (${type})`,
      `Label: ${server.label || server.name}`,
      `Status: ${server.status}${server.suspendReason ? ` (suspended: ${server.suspendReason})` : ""}`,
      `Hostname: ${server.hostname}`,
      server.ipAddress ? `IPv4: ${server.ipAddress}` : null,
      server.ipv6 ? `IPv6: ${server.ipv6}` : null,
      `Specs: ${specs}`,
      type === "game" && server.gamePlan
        ? `Game: ${server.gamePlan.gameFamily}${server.gameVariant ? ` (${server.gameVariant})` : ""}, ${server.gamePlan.slots ?? "?"} slots, plan "${server.gamePlan.name}"`
        : server.plan
          ? `Plan: ${server.plan.name}`
          : null,
      type === "nxcloud" && server.nxcloudInstance
        ? `Nextcloud: ${server.nxcloudInstance.subdomain} — ${server.nxcloudInstance.status}${server.nxcloudInstance.version ? `, v${server.nxcloudInstance.version}` : ""}, storage ${server.nxcloudInstance.storageUsedMB ?? "?"}/${server.nxcloudInstance.storageQuotaMB} MB`
        : null,
      `Billing: term=${server.termMonths}mo, autoRenew=${server.autoRenew}, free=${server.isFree}, renews=${ymd(server.expiresAt)}`,
      server.dunningStage ? `Dunning: ${server.dunningStage} failed charge attempt(s) this period` : null,
      server.provisionError ? `Last error: ${server.provisionError}` : null,
    );
  }

  // --- Shared hosting account ---
  const hosting = await db.hostingAccount.findFirst({
    where: { id, userId },
    select: {
      id: true,
      primaryDomain: true,
      username: true,
      status: true,
      phpVersion: true,
      diskQuotaMB: true,
      diskUsedMB: true,
      maxSites: true,
      maxDatabases: true,
      sslActive: true,
      healthNote: true,
      error: true,
      expiresAt: true,
      plan: { select: { name: true } },
    },
  });
  if (hosting) {
    return lines(
      `SERVICE ${hosting.id} (hosting)`,
      `Primary domain: ${hosting.primaryDomain}`,
      `Status: ${hosting.status}`,
      `Plan: ${hosting.plan?.name ?? "?"} — PHP ${hosting.phpVersion}, ${hosting.maxSites} site(s), ${hosting.maxDatabases} database(s)`,
      `Disk: ${hosting.diskUsedMB ?? "?"} / ${hosting.diskQuotaMB} MB used`,
      `SSL active: ${hosting.sslActive}`,
      `Renews: ${ymd(hosting.expiresAt)}`,
      hosting.healthNote ? `Health: ${hosting.healthNote}` : null,
      hosting.error ? `Last error: ${hosting.error}` : null,
    );
  }

  // --- Business-email subscription ---
  const email = await db.emailSubscription.findFirst({
    where: { id, userId },
    select: {
      id: true,
      domainName: true,
      status: true,
      verified: true,
      external: true,
      autoRenew: true,
      expiresAt: true,
      emailPlan: { select: { name: true, mailboxes: true, storageGB: true } },
      mailboxes: { select: { address: true, status: true, quotaMB: true } },
    },
  });
  if (email) {
    const boxes = email.mailboxes
      .slice(0, 10)
      .map((m) => `  ${m.address} — ${m.status}${m.quotaMB ? ` (${m.quotaMB} MB)` : ""}`)
      .join("\n");
    return lines(
      `SERVICE ${email.id} (email)`,
      `Domain: ${email.domainName}${email.external ? " (external)" : ""}`,
      `Status: ${email.status}, verified=${email.verified}`,
      `Plan: ${email.emailPlan?.name ?? "?"} — up to ${email.emailPlan?.mailboxes ?? "?"} mailbox(es) @ ${email.emailPlan?.storageGB ?? "?"} GB`,
      `Mailboxes (${email.mailboxes.length}):`,
      boxes || "  (none provisioned)",
      `Billing: autoRenew=${email.autoRenew}, renews=${ymd(email.expiresAt)}`,
    );
  }

  // --- Domain ---
  const domain = await db.domain.findFirst({
    where: { id, userId },
    select: {
      id: true,
      name: true,
      status: true,
      registrar: true,
      autoRenew: true,
      whoisPrivacy: true,
      nameservers: true,
      registeredAt: true,
      expiresAt: true,
      transferStatus: true,
      error: true,
    },
  });
  if (domain) {
    return lines(
      `SERVICE ${domain.id} (domain)`,
      `Name: ${domain.name}`,
      `Status: ${domain.status}${domain.transferStatus ? ` (transfer: ${domain.transferStatus})` : ""}`,
      `Registrar: ${domain.registrar}, WHOIS privacy=${domain.whoisPrivacy}, autoRenew=${domain.autoRenew}`,
      domain.nameservers.length ? `Nameservers: ${domain.nameservers.join(", ")}` : null,
      `Registered: ${ymd(domain.registeredAt)}, expires: ${ymd(domain.expiresAt)}`,
      domain.error ? `Last error: ${domain.error}` : null,
    );
  }

  // --- Storage volume ---
  const volume = await db.volume.findFirst({
    where: { id, userId },
    select: {
      id: true,
      name: true,
      status: true,
      sizeGB: true,
      inUse: true,
      mountPath: true,
      fsType: true,
      expiresAt: true,
      server: { select: { id: true, name: true, label: true } },
    },
  });
  if (volume) {
    return lines(
      `SERVICE ${volume.id} (volume)`,
      `Name: ${volume.name}`,
      `Status: ${volume.status}, size=${volume.sizeGB} GB, inUse=${volume.inUse}`,
      volume.server ? `Attached to: ${volume.server.label || volume.server.name} [${volume.server.id}]` : "Attached to: (none)",
      volume.mountPath ? `Mount: ${volume.mountPath}${volume.fsType ? ` (${volume.fsType})` : ""}` : null,
      `Renews: ${ymd(volume.expiresAt)}`,
    );
  }

  // --- Managed Nextcloud (looked up by its own id, if not caught as a Server) ---
  const nx = await db.nxCloudInstance.findFirst({
    where: { id, userId },
    select: {
      id: true,
      subdomain: true,
      customDomain: true,
      status: true,
      version: true,
      sslActive: true,
      storageQuotaMB: true,
      storageUsedMB: true,
      error: true,
      plan: { select: { name: true } },
      server: { select: { id: true, status: true, expiresAt: true } },
    },
  });
  if (nx) {
    return lines(
      `SERVICE ${nx.id} (nxcloud)`,
      `Access: ${nx.customDomain || `${nx.subdomain}.nxcloud.nxeon.cloud`}`,
      `Status: ${nx.status}${nx.version ? `, v${nx.version}` : ""}, SSL=${nx.sslActive}`,
      `Plan: ${nx.plan?.name ?? "?"}`,
      `Storage: ${nx.storageUsedMB ?? "?"} / ${nx.storageQuotaMB} MB`,
      nx.server ? `Backing VM: [${nx.server.id}] ${nx.server.status}, renews ${ymd(nx.server.expiresAt)}` : null,
      nx.error ? `Last error: ${nx.error}` : null,
    );
  }

  return "not found or not yours";
}

async function listInvoices(
  userId: string,
  input: unknown,
  money: (c: number) => string,
): Promise<string> {
  let limit = 10;
  if (typeof input === "object" && input && "limit" in input) {
    const n = Number((input as { limit: unknown }).limit);
    if (Number.isFinite(n)) limit = Math.max(1, Math.min(10, Math.floor(n)));
  }

  const invoices = await db.invoice.findMany({
    where: { userId },
    orderBy: { createdAt: "desc" },
    take: limit,
    select: {
      number: true,
      amountCents: true,
      refundedCents: true,
      status: true,
      description: true,
      createdAt: true,
      paidAt: true,
    },
  });

  if (!invoices.length) return "This customer has no invoices.";

  const rows = invoices.map((i) => {
    const refunded = i.refundedCents > 0 ? ` (refunded ${money(i.refundedCents)})` : "";
    return `#${i.number} ${ymd(i.createdAt)} — ${money(i.amountCents)}${refunded} — ${i.status} — ${i.description}`;
  });
  return lines(`INVOICES (most recent ${invoices.length}):`, ...rows);
}

async function billingStatus(userId: string, money: (c: number) => string): Promise<string> {
  const now = new Date();
  const [user, openInvoices, overdueServers, nextRenewal] = await Promise.all([
    db.user.findUnique({
      where: { id: userId },
      select: {
        balanceCents: true,
        signupCreditCents: true,
        cardBrand: true,
        cardLast4: true,
        cardExpMonth: true,
        cardExpYear: true,
        stripeCustomerId: true,
        stripePaymentMethodId: true,
      },
    }),
    db.invoice.findMany({
      where: { userId, status: "OPEN" },
      orderBy: { createdAt: "desc" },
      select: { number: true, amountCents: true, description: true, createdAt: true },
    }),
    db.server.findMany({
      where: {
        userId,
        isFree: false,
        expiresAt: { lt: now },
        status: { in: ["RUNNING", "STOPPED", "SUSPENDED"] },
      },
      orderBy: { expiresAt: "asc" },
      take: 20,
      select: {
        id: true,
        name: true,
        label: true,
        status: true,
        expiresAt: true,
        dunningStage: true,
        dunningNextAt: true,
        suspendReason: true,
      },
    }),
    db.server.findFirst({
      where: { userId, isFree: false, autoRenew: true, expiresAt: { gte: now }, status: { in: ["RUNNING", "STOPPED"] } },
      orderBy: { expiresAt: "asc" },
      select: { expiresAt: true },
    }),
  ]);

  if (!user) return "Error: customer not found.";

  const cardLabel = cardDisplayLabel(user);
  const chargeable = hasChargeableCard(user);
  const unpaidTotal = openInvoices.reduce((n, i) => n + i.amountCents, 0);
  const creditCents = user.balanceCents + user.signupCreditCents;

  const overdueLines = overdueServers.map((s) => {
    const stage = s.dunningStage
      ? `${s.dunningStage} failed charge attempt(s)`
      : "awaiting first retry";
    const next = s.dunningNextAt ? `, next retry ${ymd(s.dunningNextAt)}` : "";
    const susp = s.suspendReason ? `, suspended: ${s.suspendReason}` : "";
    return `  [${s.id}] ${s.label || s.name} — ${s.status}, due ${ymd(s.expiresAt)} — ${stage}${next}${susp}`;
  });

  return lines(
    "BILLING STATUS",
    `Payment card on file: ${cardLabel ? cardLabel : "none"}`,
    cardLabel ? `Chargeable off-session: ${chargeable ? "yes" : "no"}` : null,
    `Wallet balance / account credit: ${money(creditCents)}`,
    `Unpaid invoices: ${openInvoices.length}${openInvoices.length ? ` totaling ${money(unpaidTotal)}` : ""}`,
    ...openInvoices.slice(0, 10).map((i) => `  #${i.number} ${ymd(i.createdAt)} — ${money(i.amountCents)} — ${i.description}`),
    `Past-due services (in dunning): ${overdueServers.length}`,
    ...overdueLines,
    `Next scheduled renewal: ${nextRenewal ? ymd(nextRenewal.expiresAt) : "—"}`,
  );
}

async function listTickets(userId: string): Promise<string> {
  const tickets = await db.ticket.findMany({
    where: { userId, status: { in: OPEN_TICKET_STATUSES as unknown as string[] } },
    orderBy: { updatedAt: "desc" },
    take: 20,
    select: {
      id: true,
      subject: true,
      status: true,
      priority: true,
      updatedAt: true,
      _count: { select: { messages: true } },
    },
  });

  if (!tickets.length) return "This customer has no open support tickets.";

  const rows = tickets.map(
    (t) =>
      `[${t.id}] "${t.subject}" — ${t.status}, priority=${t.priority}, ${t._count.messages} message(s), updated ${ymd(t.updatedAt)}`,
  );
  return lines(`OPEN TICKETS (${tickets.length}):`, ...rows);
}

