import "server-only";
import { db } from "@/lib/db";
import type { TicketStatus } from "@prisma/client";
import type { ClaudeToolDef } from "@/lib/anthropic";
import { formatMoney, currentCurrency } from "@/lib/tax";
import { cardDisplayLabel, hasChargeableCard } from "@/lib/stripe-cards";

/** Statuses treated as "still open" for a support ticket (i.e. not CLOSED). */
const OPEN_TICKET_STATUSES: TicketStatus[] = ["OPEN", "ANSWERED", "CUSTOMER_REPLY"];

/** Map the User's stored card mirror fields onto the shared CardDisplay shape. */
function cardOf(user: {
  cardBrand: string | null;
  cardLast4: string | null;
  cardExpMonth: number | null;
  cardExpYear: number | null;
}) {
  return {
    brand: user.cardBrand,
    last4: user.cardLast4,
    expMonth: user.cardExpMonth,
    expYear: user.cardExpYear,
  };
}

